// Using Jedis to update a leaderboard and fetch top 3 players
jedis.zadd("game:leaderboard", 1500.0, "player_1");
jedis.zadd("game:leaderboard", 2200.0, "player_2");
jedis.zadd("game:leaderboard", 1800.0, "player_3");

// Fetch top 3 players by score descending
Set<String> topPlayers = jedis.zrevrange("game:leaderboard", 0, 2);

// Get a specific player's rank (0-indexed)
Long rank = jedis.zrevrank("game:leaderboard", "player_3");
